// Enumerate the two remaining six-edit branches. A removable edge plus a blue six gives
// a blue eight. An addition must lie inside every such eight for that removal to be usable.
use std::io::{self,BufRead};
fn meet(a:&[u32;27],mut p:u32,k:u32,q:u32,acc:&mut u32){if k==0{*acc &= q;return}while p.count_ones()>=k{let i=p.trailing_zeros() as usize;p&=p-1;meet(a,p&!a[i],k-1,q|1<<i,acc)}}
fn blue(a:&[u32;27],mut p:u32,k:u32)->bool{if k==0{return true}while p.count_ones()>=k{let i=p.trailing_zeros() as usize;p&=p-1;if blue(a,p&!a[i],k-1){return true}}false}
type E=(usize,usize);
fn flip(a:&mut[u32;27],(i,j):E){a[i]^=1<<j;a[j]^=1<<i;}
fn dfs(a:&mut[u32;27],p:u32,opts:&[E],k:usize,add:Option<E>,st:&mut[u64;4])->bool{if opts.len()<k{return false}if k==0{if let Some((i,j))=add{if a[i]&a[j]&p!=0{return false}}st[1]+=1;let mut h=[0;28];let mut f=0;for i in 0..27{if p>>i&1!=0{let d=(a[i]&p).count_ones();h[d as usize]+=1;if d==4{f|=1<<i}}}if h[4]!=6||h[6]!=12||h[7]!=8{return false}st[2]+=1;if (0..27).any(|i|f>>i&1==1&&(a[i]&f).count_ones()>1){return false}st[3]+=1;return true}
let mut any=false;for (pos,&(i,j)) in opts.iter().enumerate(){if opts.len()-pos<k{break}if blue(a,p&!a[i]&!a[j]&!(1<<i)&!(1<<j),6){continue}flip(a,(i,j));any|=dfs(a,p,&opts[pos+1..],k-1,add,st);flip(a,(i,j))}any}
fn main(){let mut st=[[0u64;4];2];let mut example=false;for l in io::stdin().lock().lines(){let l=l.unwrap();let (idx,g)=l.split_once(' ').unwrap();let bytes=g.as_bytes();let mut a=[0;27];let mut ec=0;let mut t=0;for j in 0..27{for i in 0..j{if (bytes[1+t/6]-63)>>(5-t%6)&1==1{flip(&mut a,(i,j));ec+=1}t+=1}}for z in 0..27{let ne=ec-a[z].count_ones();if ne!=80&&ne!=82{continue}let mixed=ne==80;let c=&mut st[mixed as usize];c[0]+=1;let p=((1<<27)-1)^(1<<z);let mut safe=vec![];let mut guards=vec![];let mut adds=vec![];for i in 0..27{if i==z{continue}for j in 0..i{if j==z{continue}if a[i]>>j&1!=0{let both=(1<<i)|(1<<j);let mut acc=u32::MAX;let pool=p&!a[i]&!a[j]&!both;if mixed{meet(&a,pool,6,both,&mut acc)}else if blue(&a,pool,6){acc=0}if acc==u32::MAX{safe.push((i,j))}else if mixed{guards.push(((i,j),acc))}}else if mixed&&(a[i]&a[j]&p).count_ones()<=5{adds.push((i,j))}}}
if mixed{let n=safe.len();for (i,j) in adds{let b=(1<<i)|(1<<j);safe.extend(guards.iter().filter(|(_,m)|m&b==b).map(|(e,_)|e));flip(&mut a,(i,j));let found=dfs(&mut a,p,&safe,5,Some((i,j)),c);flip(&mut a,(i,j));safe.truncate(n);if found&&!example{eprintln!("possible core {} {} add {} {}",idx,z,i,j);example=true}}}else{let found=dfs(&mut a,p,&safe,6,None,c);if found&&!example{eprintln!("possible core {} {} no add",idx,z);example=true}}}}println!("{:?}",st)}
